ST.xhtml:
parts.u1(
    number := 1,
    operatorStatus := statuses.operatorStatus,
    activityStatus := statuses.activityStatus,
    services := parts.services);
parts.u2(
    number := 2,
    operatorStatus := statuses.operatorStatus,
    activityStatus := statuses.activityStatus,
    services := parts.services);
parts.u3(
    number := 3,
    operatorStatus := statuses.operatorStatus,
    activityStatus := statuses.activityStatus,
    services := parts.services);
parts.u4(
    number := 4,
    operatorStatus := statuses.operatorStatus,
    activityStatus := statuses.activityStatus,
    services := parts.services);
parts.services( operatorStatus := statuses.operatorStatus );
statuses.initializationStatus();
statuses.healthStatus(
    superState := NOT(statuses.initializationStatus.shutdown),
    isGood := parts.u1.statuses.healthStatus.isGood AND (parts.u2.statuses.healthStatus.isGood AND (parts.u3.statuses.healthStatus.isGood AND (parts.u4.statuses.healthStatus.isGood AND parts.services.statuses.healthStatus.isGood))),
    hasWarning := parts.u1.statuses.healthStatus.hasWarning OR (parts.u2.statuses.healthStatus.hasWarning OR (parts.u3.statuses.healthStatus.hasWarning OR (parts.u4.statuses.healthStatus.hasWarning OR parts.services.statuses.healthStatus.hasWarning))));
statuses.busyStatus(
    superState := NOT(statuses.initializationStatus.shutdown),
    isBusy := parts.u1.statuses.busyStatus.busy OR (parts.u2.statuses.busyStatus.busy OR (parts.u3.statuses.busyStatus.busy OR (parts.u4.statuses.busyStatus.busy OR parts.services.statuses.busyStatus.busy))));
statuses.operatorStatus();
statuses.passwordHealthStatus( superState := statuses.operatorStatus.observer );
statuses.activityStatus();
processes.initialize( isEnabled := NOT(statuses.initializationStatus.initializing) );
processes.lock( isEnabled := statuses.operatorStatus.tech AND statuses.initializationStatus.initialized );
processes.unlock( isEnabled := statuses.operatorStatus.tech AND statuses.initializationStatus.locked );
processes.changeOperator( isEnabled := TRUE );
processes.verifyPassword( isEnabled := TRUE );
processes.wakeUp( isEnabled := TRUE );
processes.goToSleep( isEnabled := TRUE );
processes.emergencyClose( isEnabled := NOT(parts.u1.parts.dome.parts.shutter.statuses.apertureStatus.closed AND (parts.u1.parts.dome.parts.shutter.statuses.apertureStatus.closed AND (parts.u1.parts.dome.parts.shutter.statuses.apertureStatus.closed AND parts.u1.parts.dome.parts.shutter.statuses.apertureStatus.closed))) );
processes.point( isEnabled := parts.u1.processes.point.isEnabled OR (parts.u2.processes.point.isEnabled OR (parts.u3.processes.point.isEnabled OR parts.u4.processes.point.isEnabled)) );
processes.openDomes( isEnabled := parts.u1.parts.dome.parts.shutter.processes.open.isEnabled OR (parts.u2.parts.dome.parts.shutter.processes.open.isEnabled OR (parts.u3.parts.dome.parts.shutter.processes.open.isEnabled OR parts.u4.parts.dome.parts.shutter.processes.open.isEnabled)) );
processes.closeDomes( isEnabled := parts.u1.parts.dome.parts.shutter.processes.close.isEnabled OR (parts.u2.parts.dome.parts.shutter.processes.close.isEnabled OR (parts.u3.parts.dome.parts.shutter.processes.close.isEnabled OR parts.u4.parts.dome.parts.shutter.processes.close.isEnabled)) );
processes.stopDomes( isEnabled := parts.u1.parts.dome.parts.shutter.processes.stop.isEnabled OR (parts.u2.parts.dome.parts.shutter.processes.stop.isEnabled OR (parts.u3.parts.dome.parts.shutter.processes.stop.isEnabled OR parts.u4.parts.dome.parts.shutter.processes.stop.isEnabled)) );

changeOperator := THIS^.processes.changeOperator.request(
    state := state,
    password := password);

verifyPassword := THIS^.processes.verifyPassword.request(
    state := state,
    password := password);

THIS^.parts.u1._log(
    name := 'u1',
    buffer := subBuffer);
THIS^.parts.u2._log(
    name := 'u2',
    buffer := subBuffer);
THIS^.parts.u3._log(
    name := 'u3',
    buffer := subBuffer);
THIS^.parts.u4._log(
    name := 'u4',
    buffer := subBuffer);
THIS^.parts.services._log(
    name := 'services',
    buffer := subBuffer);
THIS^.processes.initialize._log(
    name := 'processes.initialize',
    buffer := subBuffer);
THIS^.processes.lock._log(
    name := 'processes.lock',
    buffer := subBuffer);
THIS^.processes.unlock._log(
    name := 'processes.unlock',
    buffer := subBuffer);
THIS^.processes.changeOperator._log(
    name := 'processes.changeOperator',
    buffer := subBuffer);
THIS^.processes.verifyPassword._log(
    name := 'processes.verifyPassword',
    buffer := subBuffer);
THIS^.processes.wakeUp._log(
    name := 'processes.wakeUp',
    buffer := subBuffer);
THIS^.processes.goToSleep._log(
    name := 'processes.goToSleep',
    buffer := subBuffer);
THIS^.processes.emergencyClose._log(
    name := 'processes.emergencyClose',
    buffer := subBuffer);
THIS^.processes.point._log(
    name := 'processes.point',
    buffer := subBuffer);
THIS^.processes.openDomes._log(
    name := 'processes.openDomes',
    buffer := subBuffer);
THIS^.processes.closeDomes._log(
    name := 'processes.closeDomes',
    buffer := subBuffer);
THIS^.processes.stopDomes._log(
    name := 'processes.stopDomes',
    buffer := subBuffer);
LOGGER(
    name := name,
    actualStatus := THIS^.actualStatus,
    previousStatus := THIS^.previousStatus,
    buffer := buffer,
    subBuffer := subBuffer,
    pHealthStatus := ADR(THIS^.statuses.healthStatus),
    pBusyStatus := ADR(THIS^.statuses.busyStatus));

IF do_request THEN
    do_request_result := request(
    alpha := set.alpha,
    delta := set.delta,
    u1 := set.u1,
    u2 := set.u2,
    u3 := set.u3,
    u4 := set.u4);
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.alpha := alpha;
THIS^.get.delta := delta;
THIS^.get.u1 := u1;
THIS^.get.u2 := u2;
THIS^.get.u3 := u3;
THIS^.get.u4 := u4;
THIS^.statuses.busyStatus( isBusy := TRUE );
THIS^.statuses.healthStatus( isGood := TRUE );

IF THIS^.statuses.enabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start(
        alpha := alpha,
        delta := delta,
        u1 := u1,
        u2 := u2,
        u3 := u3,
        u4 := u4);
ELSE
    request := RequestResults.REJECTED;
END_IF;

IF do_request THEN
    do_request_result := request(
    u1 := set.u1,
    u2 := set.u2,
    u3 := set.u3,
    u4 := set.u4);
    do_request := FALSE;
END_IF;
SUPER^();

THIS^.get.u1 := u1;
THIS^.get.u2 := u2;
THIS^.get.u3 := u3;
THIS^.get.u4 := u4;
THIS^.statuses.busyStatus( isBusy := TRUE );
THIS^.statuses.healthStatus( isGood := TRUE );

IF THIS^.statuses.enabledStatus.enabled THEN
    request := RequestResults.ACCEPTED;
    THIS^.start(
        u1 := u1,
        u2 := u2,
        u3 := u3,
        u4 := u4);
ELSE
    request := RequestResults.REJECTED;
END_IF;
